const fs = require('fs');

const INF = 1000000001;

class Pair {
	constructor(first, second) {
		this.first = first;
		this.second = second;
	}
}

function sort(arr, from, to) {
	if (from === undefined) from = 0;
	if (to === undefined) to = arr.length;
	const len = to - from;
	if (len < 2) {
		return arr;
	}
	let left = 0;
	let right = len - 1;
	const pivot = Math.floor(len / 2);

	let tmp = arr[from + pivot];
	arr[from + pivot] = arr[from + right];
	arr[from + right] = tmp;

	for (let i = 0; i < len; i++) {
		if (arr[from + i] < arr[from + right]) {
			tmp = arr[from + i];
			arr[from + i] = arr[from + left];
			arr[from + left] = tmp;
			left++;
		}
	}

	tmp = arr[from + left];
	arr[from + left] = arr[from + right];
	arr[from + right] = tmp;

	sort(arr, from, from + left);
	sort(arr, from + left + 1, to);
	return arr;
}

function check(n) {
	let s = 0;
	while (n > 0) {
		s += n % 10;
		n = Math.floor(n / 10);
	}
	return s === 10;
}

function solution(input, out) {
	const tokens = input.split(/\s+/).filter(s => s.length > 0);
	let k = parseInt(tokens[0], 10);
	for (let i = 19; k > 0; i++) {
		if (check(i)) {
			k--;
		}
		if (k === 0) {
			out(String(i));
			return;
		}
	}
}

function main() {
	const input = fs.readFileSync(0, 'utf8');
	const buffer = [];
	solution(input, (s) => buffer.push(s));
	process.stdout.write(buffer.join('\n') + (buffer.length > 0 ? '\n' : ''));
}

main();
